-- S1 · parte 2.01: proyectos y-el-ano-que-viene-que, 100-baladas-arkano, el-cirujano
create function pg_temp.med(u text) returns uuid language sql as $$ select id from public.medios where url_origen = u order by creado_en limit 1 $$;
create function pg_temp.gal(urls text[]) returns jsonb language sql as $$ select coalesce(jsonb_agg(jsonb_build_object('medio', pg_temp.med(u), 'pie', '') order by o), '[]'::jsonb) from unnest(urls) with ordinality t(u, o) $$;

insert into public.proyectos (id_antiguo, slug, titulo, tipo_id, anio, direccion, productora, papel, camara, premios, tarjeta, historia, como_lo_hicimos, el_reto, el_resultado, frase,
  youtube_id, youtube_inicio, videos, videos_debajo_del_texto, imagen_id, galeria, destacado_orden, orden, estado, publicado_en)
values ('y-el-ano-que-viene-que', 'y-el-ano-que-viene-que', 'Y el año que viene, ¿qué?', (select id from public.tipos_proyecto where slug = 'cortometraje'), 2024, 'Josep Mira Lozano',
  'Proyecto propio · ESCAC Dreammakers, Cupra', 'Guion, dirección, fotografía y montaje', 'Sony FX3 · Tamron', $t$[{"anio":2024,"nombre":"Podio","tipo":"podio","festival":"ESCAC Dreammakers Contest 2024"}]$t$::jsonb,
  $t$El ESCAC Dreammakers Contest de Cupra pedía un corto con tres palabras obligatorias: *Ojo*, *Cine* y *Barcelona*.$t$, $t$Las uní de la única forma que me parecía honesta, contando mi propia relación con el cine. Es un relato autobiográfico en voz en off, y también me puse delante de la cámara. Me ayudaron Adrià Mira Lozano y Lara Ruiz Martín.$t$, $t$- **La voz primero.** Escribí la narración antes que nada, con *Amélie* como referencia: cálida y cercana.
- **Contraste de ritmos.** Un montaje acelerado contra una voz tranquila. De ahí sale la energía.$t$, $t$El plazo real fue de unos 15 días para idear, rodar, montar y entregar. Lo resolví quedándome solo con lo que contaba la historia.$t$, $t$- Podio del ESCAC Dreammakers Contest 2024.
- Acceso a becas de la ESCAC.$t$, $t$Un concurso me pidió tres palabras. Le respondí con *mi historia*.$t$,
  'dHp3YUb1x2I', 30, $t$[]$t$::jsonb, false, pg_temp.med('https://i.imgur.com/ESU7wLA.jpeg'), pg_temp.gal(array['https://i.imgur.com/ESU7wLA.jpeg','https://i.imgur.com/qtM2MCm.jpg','https://i.imgur.com/FdyOIDU.jpg']), 1, 1, 'publicado', now())
