values ('100-baladas-arkano', '100-baladas-arkano', '100 Baladas, Arkano', (select id from public.tipos_proyecto where slug = 'videoclip'), null, 'Josep Mira Lozano (idea de Álex Gómez)',
  'JUNO Media', 'Dirección, cámara y montaje', 'Sony FX3 · Tamron', $t$[]$t$::jsonb,
  $t$Una canción de amor de Arkano, escrita con su pareja y estrenada un 14 de febrero.$t$, $t$La idea de partida era de Álex Gómez: una pareja que se va acercando a lo largo del tema. Mi trabajo fue convertirla en un videoclip rodable y con ritmo, con la producción de Noelia Fluxà y Julie-Estel Soard.$t$, $t$- **La distancia como hilo.** Plano a plano, Arkano y su pareja se acercan hasta el final del tema.
- **Montaje a la canción.** Los cortes siguen los cambios del tema, no un ritmo fijo.$t$, $t$Dirigir una idea ajena sin perder lo que la hacía especial. La ajusté a la duración y al pulso de un videoclip sin tocar su centro: el acercamiento.$t$, $t$- Más de 17.000 visualizaciones en YouTube.$t$, $t$Todo el videoclip cabe en un solo gesto: *acercarse*.$t$,
  'AWHJJA92MXM', 25, $t$[]$t$::jsonb, false, pg_temp.med('https://i.ytimg.com/vi/AWHJJA92MXM/maxresdefault.jpg'), pg_temp.gal(array['https://i.ytimg.com/vi/AWHJJA92MXM/maxresdefault.jpg','https://i.imgur.com/7Cs37zX.png','https://i.imgur.com/fkGQTMm.png','https://i.imgur.com/NWdrT3L.png','https://i.imgur.com/6u1rfiM.png','https://i.imgur.com/r00RLoG.png']), 2, 2, 'publicado', now())
